 static void MigrationChecks(string list){
  var oldRoot=GameInstallation.ModsRoot+"/BasicM4";var newRoot=GameInstallation.ModsRoot+"/BeyondApocalypse";
  var record=store.List().First(x=>x.Id=="beyondapocalypse");record.Id="basicm4";var manifests=Path.Combine(store.DataPath,"manifests");File.Delete(Path.Combine(manifests,"beyondapocalypse.json"));Write(Path.Combine(manifests,"basicm4.json"),new JavaScriptSerializer().Serialize(record));
  Write(P(oldRoot+"/State/world.json"),"saved world");Write(P(oldRoot+"/UserSettings.ini"),"my keys");Write(P(oldRoot+"/Scripts/config.lua"),"my configuration");Write(P(oldRoot+"/extras/my-file.txt"),"unknown preserved");
  store.SetEnabled("beyondapocalypse",false);store.SetEnabled("beyondapocalypse",true);Assert(File.Exists(P(oldRoot+"/State/world.json")),"Canonical alias lost legacy disabled state");
  var canonical=Zip("canonical","BeyondApocalypse/Scripts/main.lua","new main","BeyondApocalypse/Scripts/release.lua","return {Version='1.0.5',Channel='beta'}","BeyondApocalypse/Scripts/config.lua","default configuration","BeyondApocalypse/enabled.txt","","BasicM4/Scripts/main.lua","-- BeyondApocalypse legacy migration shim v1\n-- no-op","BasicM4/Scripts/release.lua","return {} ");
  var plan=store.PreviewZip(canonical);Assert(plan.Id=="beyondapocalypse"&&plan.LuaRoots.Count==1&&!plan.Files.Any(x=>x.Path.Contains("/BasicM4/")),"Shim imported as a separate active mod");Assert(!plan.ExistingUnmanaged,"Managed legacy install wrongly needs unmanaged adoption");
  using(var held=new FileStream(list,FileMode.Open,FileAccess.Read,FileShare.Read))Refuse(()=>store.Install(plan),"legacy migration locked-file rollback");Assert(File.ReadAllText(P(oldRoot+"/Scripts/main.lua"))=="main"&&!Directory.Exists(P(newRoot))&&File.Exists(Path.Combine(manifests,"basicm4.json")),"Migration rollback did not restore old folder/manifest");
  store.Install(plan);Assert(!Directory.Exists(P(oldRoot))&&File.ReadAllText(P(newRoot+"/State/world.json"))=="saved world"&&File.ReadAllText(P(newRoot+"/UserSettings.ini"))=="my keys"&&File.ReadAllText(P(newRoot+"/Scripts/config.lua"))=="my configuration"&&File.Exists(P(newRoot+"/extras/my-file.txt")),"Migration lost state/config/unknown files");Assert(!File.Exists(Path.Combine(manifests,"basicm4.json"))&&store.List().Count(x=>ModStore.IsBeyondIdentity(x.Id))==1,"Migration retained duplicate identity");Assert(!File.ReadAllText(list).Contains("BasicM4 :")&&File.ReadAllText(list).Contains("BeyondApocalypse : 1"),"Legacy load row retained");
  var dependent=store.PreviewZip(Zip("rename-dependent","Dependent/Scripts/main.lua","main","bmm.json","{\"dependencies\":[\"basicm4\"]}"));Assert(dependent.MissingDependencies.Count==0,"Legacy dependency identity failed after rename");store.Install(dependent);Refuse(()=>store.SetEnabled("beyondapocalypse",false),"legacy dependency protection after rename");Assert(File.ReadAllText(list).IndexOf("BeyondApocalypse : 1",StringComparison.Ordinal)<File.ReadAllText(list).IndexOf("Dependent : 1",StringComparison.Ordinal),"Legacy dependency ordered before renamed mod");store.Uninstall("dependent");
  store.SetEnabled("basicm4",false);Assert(!Directory.Exists(P(newRoot))&&!Directory.Exists(P(oldRoot)),"Disabled renamed mod left active folder");store.SetEnabled("beyondapocalypse",true);store.Uninstall("basicm4");Assert(!File.Exists(P(newRoot+"/Scripts/main.lua"))&&!File.Exists(P(oldRoot+"/Scripts/main.lua"))&&File.Exists(P(newRoot+"/State/world.json")),"Uninstall ghost loader or lost state");
  // A separate existing unmanaged installation requires deliberate adoption.
  var externalGame=Path.Combine(root,"LegacyGame");Write(Path.Combine(externalGame,GameInstallation.BinaryRoot.Replace('/',Path.DirectorySeparatorChar),"DriveBeyondHorizons-Win64-Shipping.exe"),"fixture");Write(Path.Combine(externalGame,GameInstallation.BinaryRoot.Replace('/',Path.DirectorySeparatorChar),"ue4ss","UE4SS.dll"),"fixture");var externalStore=new ModStore(externalGame,data,()=>false);var externalOld=Path.Combine(externalGame,oldRoot.Replace('/',Path.DirectorySeparatorChar));var externalNew=Path.Combine(externalGame,newRoot.Replace('/',Path.DirectorySeparatorChar));Write(Path.Combine(externalOld,"Scripts","main.lua"),"old unmanaged");Write(Path.Combine(externalOld,"UserSettings.ini"),"external keys");var adopt=externalStore.PreviewZip(canonical);Assert(adopt.ExistingUnmanaged,"Unmanaged rename adoption not announced");Refuse(()=>externalStore.Install(adopt),"unmanaged rename without adoption");externalStore.Install(adopt,true);Assert(!Directory.Exists(externalOld)&&File.ReadAllText(Path.Combine(externalNew,"UserSettings.ini"))=="external keys","Unmanaged migration lost settings");
  Write(Path.Combine(externalOld,"Scripts","main.lua"),"duplicate actual mod");Refuse(()=>externalStore.PreviewZip(canonical),"ambiguous duplicate active roots");Write(Path.Combine(externalOld,"Scripts","main.lua"),"-- BeyondApocalypse legacy migration shim v1\n-- no-op");Write(Path.Combine(externalOld,"State","old-only.json"),"legacy state");Assert(externalStore.List().Count(x=>x.Name=="Beyond Apocalypse")==1,"Inert legacy shim counted as mod");externalStore.Install(externalStore.PreviewZip(canonical));Assert(!Directory.Exists(externalOld)&&File.ReadAllText(Path.Combine(externalNew,"State","old-only.json"))=="legacy state","Existing shim state was not preserved");externalStore.SetEnabled("beyondapocalypse",false);Assert(!Directory.Exists(externalOld)&&!Directory.Exists(externalNew),"Shim caused ghost-load after disable");
