  Refuse(()=>store.PreviewZip(Zip("privatemetadata","Other/Scripts/main.lua","main","bmm.json","{\"id\":\"beyondapocalypse\"}","BeyondApocalypseDevMenu/Scripts/attach.lua","private")),"BA metadata with private companion");
  Refuse(()=>store.PreviewZip(Zip("privatealiasmenu","Other/Scripts/main.lua","main","bmm.json","{\"id\":\"beyondapocalypse\"}","Other/Scripts/devmenu/ui.lua","private")),"BA metadata with renamed embedded menu");
  Refuse(()=>store.PreviewZip(Zip("privatealiasattach","Other/Scripts/main.lua","main","bmm.json","{\"id\":\"beyondapocalypse\"}","Other/Scripts/attach.lua","private")),"BA metadata with renamed private attachment source");
  Assert(store.PreviewZip(Zip("communitydev","Community/Scripts/main.lua","main","Community/Scripts/devmenu/ui.lua","community UI")).Files.Count==2,"Unrelated community dev menu blocked");
  var isolated=Path.Combine(root,"PrivateIsolation");var bin=Path.Combine(isolated,GameInstallation.BinaryRoot.Replace('/',Path.DirectorySeparatorChar));var mods=Path.Combine(isolated,GameInstallation.ModsRoot.Replace('/',Path.DirectorySeparatorChar));Write(Path.Combine(bin,"DriveBeyondHorizons-Win64-Shipping.exe"),"fixture");Write(Path.Combine(bin,"ue4ss","UE4SS.dll"),"fixture");var local=new ModStore(isolated,data,()=>false);var clean=Zip("cleanpublic","BeyondApocalypse/Scripts/main.lua","public main","BeyondApocalypse/Scripts/optional_interface.lua","optional read-only companion hook");
  local.Install(local.PreviewZip(clean));var companion=Path.Combine(mods,"BeyondApocolypseDevMenu");Assert(!Directory.Exists(companion)&&!local.List().Any(x=>x.Kind=="Companion"),"Clean BA install created a private companion");var journal=Path.Combine(mods,"BeyondApocalypse","state","transport-fixture.txt");Assert(File.Exists(Path.Combine(mods,"BeyondApocalypse","state","KEEP THIS FOLDER.txt")),"Historical launcher archive left journal directory missing");Write(journal,"existing saved identity");
  var attach=Path.Combine(companion,"Scripts","attach.lua");Write(attach,"existing private file");var hash=ModStore.HashFile(attach);var stamp=File.GetLastWriteTimeUtc(attach);local.Install(local.PreviewZip(clean));Assert(ModStore.HashFile(attach)==hash&&File.GetLastWriteTimeUtc(attach)==stamp&&Directory.EnumerateFiles(companion,"*",SearchOption.AllDirectories).Count()==1,"BA reinstall changed existing private files");Assert(local.List().Any(x=>x.Kind=="Companion"),"Existing companion should be accurately rediscovered");
